307	                        Map.of("requestId", "cancel-rk"))
308	                .andExpect(status().isOk())
309	                .andExpect(jsonPath("$.status").value("CANCELLED"));
310	        // 同 requestId 用于取消其他插播：409
311	        postJson("/api/emergency-overrides/" + ctx.key("io") + "/cancel",
312	                        Map.of("requestId", "cancel-rk"))
313	                .andExpect(status().isConflict())
314	                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));
315	
316	        // 重放创建不能复活已取消插播：
317	        // 新 requestId 用同键再创建 → 409，明细仍 CANCELLED
318	        createOverride(ctx, "resurrect-1", "rk", ctx.newsAsset, ctx.newsGrant, 5,
319	                        "2026-09-22T12:00:00.000+08:00", "2026-09-22T12:10:00.000+08:00")
320	                .andExpect(status().isConflict())
