322	        getOverride(ctx, "rk").andExpect(jsonPath("$.status").value("CANCELLED"));
323	        // 原创建 requestId 重放只返回历史响应，不改变 CANCELLED 状态
324	        createOverrideRaw("retry-1", ctx.key("rk"), ctx.channel, ctx.newsAsset, ctx.newsGrant, 5,
325	                        "2026-09-22T12:00:00.000+08:00", "2026-09-22T12:10:00.000+08:00")
