        // 422：指定授权已撤销（撤销先提交）
        long revokedGrant = createGrant(ctx.channel, ctx.alertAsset, GRANT_FROM, GRANT_TO);
        postJson("/api/grants/" + revokedGrant + "/revoke", Map.of("requestId", "rv-g"))
