        // 与另一条不同优先级的区间重叠不受影响（已在上面验证 3 级可重叠；这里重叠已有 5 级 nf1）
        createOverrideRaw("ov-3", ctx.key("ov-3"), ctx.channel, ctx.alertAsset,
                        ctx.alertGrant, 9, T_1025, T_1035)
