        postJson("/api/emergency-overrides", body)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("ACTIVE"))
                .andExpect(jsonPath("$.overrideKey").value(ctx.key("io")));
        // 同 requestId 改参数（优先级）：409
